module benchmark/solution

import std/env (getArgs)
import std/fs (readFile)
import std/string (split, trim, stringToInt)
import std/list (foldl)
import std/option (Some, None)

pure func parseLine(line: string) -> int =
  match stringToInt(trim(line)) {
    Some(n) => n,
    None => 0
  }

pure func sumLines(lines: [string]) -> int =
  foldl(func(acc: int, line: string) -> int { acc + parseLine(line) }, 0, lines)

export func main() -> () ! {IO, FS, Env} {
  let args = getArgs();
  match args {
    filename :: _ => {
      let content = readFile(filename);
      let lines = split(content, "\n");
      let total = sumLines(lines);
      println(show(total))
    },
    _ => println("Usage: program <filename>")
  }
}

