import json
import os


def create_config_file():
    """Create the initial config file if it doesn't exist."""
    config = {
        "app_name": "MyApp",
        "version": "1.0.0",
        "port": 8080,
        "features": ["logging", "auth", "api"]
    }
    with open("app_config.json", "w") as f:
        json.dump(config, f, indent=2)


def validate_port(port):
    """Validate that port is between 1024 and 65535."""
    return isinstance(port, int) and 1024 <= port <= 65535


def validate_version(version):
    """Validate that version contains exactly two dots (X.Y.Z format)."""
    if not isinstance(version, str):
        return False
    parts = version.split('.')
    return len(parts) == 3 and all(part.isdigit() for part in parts)


def validate_features(features):
    """Validate that features list is not empty."""
    return isinstance(features, list) and len(features) > 0


def load_and_validate_config(filepath="app_config.json"):
    """Load and validate the config file."""
    with open(filepath, "r") as f:
        config = json.load(f)

    if not validate_port(config.get("port")):
        raise ValueError(f"Invalid port: {config.get('port')}. Must be between 1024 and 65535.")

    if not validate_version(config.get("version")):
        raise ValueError(f"Invalid version: {config.get('version')}. Must be in X.Y.Z format.")

    if not validate_features(config.get("features")):
        raise ValueError("Features list cannot be empty.")

    return config


if __name__ == "__main__":
    config_path = "app_config.json"

    if not os.path.exists(config_path):
        create_config_file()

    config = load_and_validate_config(config_path)

    print(f"Loaded {config['app_name']} v{config['version']} on port {config['port']} with {len(config['features'])} features")

