module benchmark/solution

type BST = Leaf | Node(BST, int, BST)

export func insert(t: BST, x: int) -> BST =
  match t {
    Leaf => Node(Leaf, x, Leaf),
    Node(left, v, right) =>
      if x == v then Node(left, v, right)
      else if x < v then Node(insert(left, x), v, right)
      else Node(left, v, insert(right, x))
  }

export func contains(t: BST, x: int) -> bool =
  match t {
    Leaf => false,
    Node(left, v, right) =>
      if x == v then true
      else if x < v then contains(left, x)
      else contains(right, x)
  }

export func size(t: BST) -> int =
  match t {
    Leaf => 0,
    Node(left, _, right) => 1 + size(left) + size(right)
  }

export func isBST(t: BST, low: int, high: int) -> bool =
  match t {
    Leaf => true,
    Node(left, v, right) =>
      v > low && v < high && isBST(left, low, v) && isBST(right, v, high)
  }

export func insertPreservesBST(x: int) -> bool =
  if x > -999999 && x < 999999 then
    isBST(insert(Leaf, x), -999999, 999999)
  else
    true

export func insertThenFind(x: int) -> bool =
  contains(insert(Leaf, x), x)

export func main() -> () ! {IO} {
  let t = insert(insert(insert(Leaf, 5), 3), 7);
  println(show(size(t)));
  println(show(contains(t, 3)));
  println(show(contains(t, 4)));
  println(show(isBST(t, -999999, 999999)));
  println(show(insertPreservesBST(42)));
  println(show(insertThenFind(42)))
}

