class Leaf:
    pass

class Node:
    def __init__(self, value, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

def insert(tree, value):
    if isinstance(tree, Leaf):
        return Node(value)
    if value < tree.value:
        tree.left = insert(tree.left, value)
    elif value > tree.value:
        tree.right = insert(tree.right, value)
    return tree

def contains(tree, value):
    if isinstance(tree, Leaf):
        return False
    if value == tree.value:
        return True
    elif value < tree.value:
        return contains(tree.left, value)
    else:
        return contains(tree.right, value)

def size(tree):
    if isinstance(tree, Leaf):
        return 0
    return 1 + size(tree.left) + size(tree.right)

def isBST(tree, min_val, max_val):
    if isinstance(tree, Leaf):
        return True
    if tree.value <= min_val or tree.value >= max_val:
        return False
    return isBST(tree.left, min_val, tree.value) and isBST(tree.right, tree.value, max_val)

def insertPreservesBST(value):
    tree = Leaf()
    tree = insert(tree, value)
    return isBST(tree, -999999, 999999)

def insertThenFind(value):
    tree = Leaf()
    tree = insert(tree, value)
    return contains(tree, value)

if __name__ == "__main__":
    tree = insert(insert(insert(Leaf(), 5), 3), 7)
    print(size(tree))
    print(contains(tree, 3))
    print(contains(tree, 4))
    print(isBST(tree, -999999, 999999))
    print(insertPreservesBST(42))
    print(insertThenFind(42))

