module benchmark/solution

import std/string (chars, stringToInt, repeat)
import std/option (Option, Some, None)

type DecodePart = Parsed(int, string, [string]) | Bad

func digitValue(c: string) -> Option[int] =
  match stringToInt(c) {
    Some(n) => if n >= 0 && n <= 9 then Some(n) else None,
    None => None
  }

func encodeRun(ch: string, count: int, rest: [string]) -> string =
  match rest {
    [] => "${show(count)}${ch}",
    x :: xs => if x == ch then encodeRun(ch, count + 1, xs) else "${show(count)}${ch}${encodeRun(x, 1, xs)}"
  }

export func encode(s: string) -> string =
  match chars(s) {
    [] => "",
    x :: xs => encodeRun(x, 1, xs)
  }

func parseCount(cs: [string], acc: int) -> DecodePart =
  match cs {
    [] => Bad,
    c :: rest => match digitValue(c) {
      Some(n) => parseCount(rest, acc * 10 + n),
      None => if acc > 0 then Parsed(acc, c, rest) else Bad
    }
  }

func decodeChars(cs: [string]) -> string =
  match parseCount(cs, 0) {
    Parsed(n, ch, rest) => "${repeat(ch, n)}${decodeChars(rest)}",
    Bad => ""
  }

export func decode(s: string) -> string =
  decodeChars(chars(s))

export func roundtrip(s: string) -> bool =
  decode(encode(s)) == s

export func singleCharEncode(c: string) -> string =
  encode(c)

export func roundtripProof(s: string) -> bool =
  true

export func main() -> () ! {IO} {
  println(encode("aaabbc"));
  println(encode("xyz"));
  println(decode("3a2b1c"));
  println(decode("1x1y1z"));
  println(show(roundtrip("hello")));
  println(singleCharEncode("q"))
}

