def encode(s):
    if not s:
        return ""

    result = []
    count = 1
    current_char = s[0]

    for i in range(1, len(s)):
        if s[i] == current_char:
            count += 1
        else:
            result.append(str(count) + current_char)
            current_char = s[i]
            count = 1

    result.append(str(count) + current_char)
    return "".join(result)


def decode(s):
    if not s:
        return ""

    result = []
    i = 0

    while i < len(s):
        count_str = ""
        while i < len(s) and s[i].isdigit():
            count_str += s[i]
            i += 1

        if i < len(s):
            char = s[i]
            count = int(count_str)
            result.append(char * count)
            i += 1

    return "".join(result)


def roundtrip(s):
    return decode(encode(s)) == s


def singleCharEncode(c):
    return encode(c)


print(encode("aaabbc"))
print(encode("xyz"))
print(decode("3a2b1c"))
print(decode("1x1y1z"))
print(roundtrip("hello"))
print(singleCharEncode("q"))

