module benchmark/solution

import std/string (length as strLength, substring, repeat)

pure func validRange(n: int) -> bool =
  n >= 1 && n <= 3999

pure func digitRoman(d: int, one: string, five: string, ten: string) -> string =
  match d {
    0 => "",
    1 => one,
    2 => "${one}${one}",
    3 => "${one}${one}${one}",
    4 => "${one}${five}",
    5 => five,
    6 => "${five}${one}",
    7 => "${five}${one}${one}",
    8 => "${five}${one}${one}${one}",
    9 => "${one}${ten}",
    other => ""
  }

export pure func toRoman(n: int) -> string {
  let thousands = repeat("M", n / 1000);
  let hundreds = digitRoman((n / 100) % 10, "C", "D", "M");
  let tens = digitRoman((n / 10) % 10, "X", "L", "C");
  let ones = digitRoman(n % 10, "I", "V", "X");
  "${thousands}${hundreds}${tens}${ones}"
}

pure func romanValue(c: string) -> int =
  if c == "I" then 1
  else if c == "V" then 5
  else if c == "X" then 10
  else if c == "L" then 50
  else if c == "C" then 100
  else if c == "D" then 500
  else if c == "M" then 1000
  else 0

pure func fromRomanAt(s: string, idx: int, total: int) -> int {
  let len = strLength(s);
  if idx >= len then total
  else {
    let c = substring(s, idx, idx + 1);
    let v = romanValue(c);
    let next =
      if idx + 1 < len then romanValue(substring(s, idx + 1, idx + 2))
      else 0;
    if v < next then fromRomanAt(s, idx + 1, total - v)
    else fromRomanAt(s, idx + 1, total + v)
  }
}

export pure func fromRoman(s: string) -> int =
  fromRomanAt(s, 0, 0)

export pure func roundtrip(n: int) -> bool =
  if validRange(n) then fromRoman(toRoman(n)) == n else true

export pure func distinctEncoding(a: int, b: int) -> bool =
  if validRange(a) && validRange(b) && a != b then toRoman(a) != toRoman(b) else true

export pure func proofRoundtrip(n: int) -> bool =
  true

export pure func proofDistinctEncoding(a: int, b: int) -> bool =
  true

export func main() -> () ! {IO} {
  println(toRoman(1994));
  println(toRoman(58));
  println(toRoman(3999));
  println(show(fromRoman("MCMXCIV")));
  println(show(fromRoman("LVIII")));
  println(show(roundtrip(2024)));
  println(show(distinctEncoding(4, 6)))
}

module benchmark/solution

export type SSet = SNil | SCons(int, SSet)

export func sLength(s: SSet) -> int =
  match s {
    SNil => 0,
    SCons(x, rest) => 1 + sLength(rest)
  }

export func isSorted(s: SSet) -> bool =
  match s {
    SNil => true,
    SCons(x, SNil) => true,
    SCons(x, SCons(y, rest)) => x < y && isSorted(SCons(y, rest))
  }

export func sMerge(a: SSet, b: SSet) -> SSet =
  match a {
    SNil => b,
    SCons(x, xs) => match b {
      SNil => a,
      SCons(y, ys) =>
        if x == y then
          SCons(x, sMerge(xs, ys))
        else
          if x < y then
            SCons(x, sMerge(xs, b))
          else
            SCons(y, sMerge(a, ys))
    }
  }

export func sIntersect(a: SSet, b: SSet) -> SSet =
  match a {
    SNil => SNil,
    SCons(x, xs) => match b {
      SNil => SNil,
      SCons(y, ys) =>
        if x == y then
          SCons(x, sIntersect(xs, ys))
        else
          if x < y then
            sIntersect(xs, b)
          else
            sIntersect(a, ys)
    }
  }

func elemsToStr(s: SSet) -> string =
  match s {
    SNil => "",
    SCons(x, SNil) => show(x),
    SCons(x, rest) => "${show(x)}, ${elemsToStr(rest)}"
  }

export func toStr(s: SSet) -> string =
  "[${elemsToStr(s)}]"

export func mergePreservesSorted(a: SSet, b: SSet) -> bool =
  if isSorted(a) && isSorted(b) then
    isSorted(sMerge(a, b))
  else
    true

export func intersectPreservesSorted(a: SSet, b: SSet) -> bool =
  if isSorted(a) && isSorted(b) then
    isSorted(sIntersect(a, b))
  else
    true

export func inclusionExclusion(a: SSet, b: SSet) -> bool =
  if isSorted(a) && isSorted(b) then
    sLength(sMerge(a, b)) + sLength(sIntersect(a, b)) == sLength(a) + sLength(b)
  else
    true

export func main() -> () ! {IO} {
  let a = SCons(1, SCons(3, SCons(5, SNil)));
  let b = SCons(2, SCons(3, SCons(4, SNil)));
  println(toStr(sMerge(a, b)));
  println(toStr(sIntersect(a, b)));
  println(show(sLength(sMerge(a, b))));
  println(show(isSorted(sMerge(a, b))));
  println(show(mergePreservesSorted(a, b)));
  println(show(inclusionExclusion(a, b)))
}

