class SNil:
    """Empty set node"""
    def __init__(self):
        pass

class SCons:
    """Set constructor with head element and tail"""
    def __init__(self, head, tail):
        self.head = head
        self.tail = tail

def toStr(s):
    """Convert set to string representation like {1, 2, 3}"""
    if isinstance(s, SNil):
        return "{}"
    elements = []
    current = s
    while isinstance(current, SCons):
        elements.append(str(current.head))
        current = current.tail
    return "{" + ", ".join(elements) + "}"

def sMerge(s1, s2):
    """Union of two sorted sets, maintaining sorted order and no duplicates"""
    if isinstance(s1, SNil):
        return s2
    if isinstance(s2, SNil):
        return s1
    if s1.head < s2.head:
        return SCons(s1.head, sMerge(s1.tail, s2))
    elif s1.head > s2.head:
        return SCons(s2.head, sMerge(s1, s2.tail))
    else:
        return SCons(s1.head, sMerge(s1.tail, s2.tail))

def sIntersect(s1, s2):
    """Intersection of two sorted sets"""
    if isinstance(s1, SNil) or isinstance(s2, SNil):
        return SNil()
    if s1.head < s2.head:
        return sIntersect(s1.tail, s2)
    elif s1.head > s2.head:
        return sIntersect(s1, s2.tail)
    else:
        return SCons(s1.head, sIntersect(s1.tail, s2.tail))

def sLength(s):
    """Return the cardinality of the set"""
    if isinstance(s, SNil):
        return 0
    return 1 + sLength(s.tail)

def isSorted(s):
    """Check if the set is sorted with no duplicates"""
    if isinstance(s, SNil):
        return True
    if isinstance(s.tail, SNil):
        return True
    if s.head >= s.tail.head:
        return False
    return isSorted(s.tail)

def mergePreservesSorted(s1, s2):
    """Proof that merge preserves sorted invariant"""
    return isSorted(sMerge(s1, s2))

def inclusionExclusion(s1, s2):
    """Proof of inclusion-exclusion principle: |A∪B| + |A∩B| == |A| + |B|"""
    return sLength(sMerge(s1, s2)) + sLength(sIntersect(s1, s2)) == sLength(s1) + sLength(s2)

# Print required outputs
print(toStr(sMerge(SCons(1, SCons(3, SCons(5, SNil()))), SCons(2, SCons(3, SCons(4, SNil()))))))
print(toStr(sIntersect(SCons(1, SCons(3, SCons(5, SNil()))), SCons(2, SCons(3, SCons(4, SNil()))))))
print(sLength(sMerge(SCons(1, SCons(3, SCons(5, SNil()))), SCons(2, SCons(3, SCons(4, SNil()))))))
print(isSorted(sMerge(SCons(1, SCons(3, SCons(5, SNil()))), SCons(2, SCons(3, SCons(4, SNil()))))))
print(mergePreservesSorted(SCons(1, SCons(3, SCons(5, SNil()))), SCons(2, SCons(3, SCons(4, SNil())))))
print(inclusionExclusion(SCons(1, SCons(3, SCons(5, SNil()))), SCons(2, SCons(3, SCons(4, SNil())))))

