module benchmark/solution

import std/fs (readFile, writeFile)
import std/string (split, trim, stringToInt, contains)
import std/list (length)
import std/json (Json, encode, jo, ja, kv, js, jnum)
import std/math (intToFloat)
import std/option (Option, Some, None)

type User = {name: string, age: int, email: string}

pure func validHeaders(headers: [string]) -> bool =
  match headers {
    h1 :: h2 :: h3 :: [] => trim(h1) == "name" && trim(h2) == "age" && trim(h3) == "email",
    _ => false
  }

pure func parseRow(row: string) -> Option[User] {
  if trim(row) == "" then None
  else {
    let cols = split(row, ",");
    match cols {
      rawName :: rawAge :: rawEmail :: [] => {
        let name = trim(rawName);
        let ageText = trim(rawAge);
        let email = trim(rawEmail);
        match stringToInt(ageText) {
          Some(age) => if age > 0 && contains(email, "@")
            then Some({name: name, age: age, email: email})
            else None,
          None => None
        }
      },
      _ => None
    }
  }
}

pure func parseRows(rows: [string]) -> [User] =
  match rows {
    [] => [],
    row :: rest => match parseRow(row) {
      Some(user) => user :: parseRows(rest),
      None => parseRows(rest)
    }
  }

pure func parseCsvLines(lines: [string]) -> [User] =
  match lines {
    [] => [],
    header :: rows => {
