    return x in lst

def enqueue(x, queue):
    queue.append(x)

def bfs(graph, start_node):
    adj_dict = {}
    for node, neighbors in graph:
        adj_dict[node] = neighbors

    queue = []
    visited = []
    result = []

    enqueue(start_node, queue)
    visited.append(start_node)

    while len(queue) > 0:
        current = queue.pop(0)
        result.append(current)

        for neighbor in adj_dict.get(current, []):
            if not contains(neighbor, visited):
                enqueue(neighbor, queue)
                visited.append(neighbor)

    return result

