from dataclasses import dataclass
from typing import Union, List, Tuple

# AST node definitions
@dataclass
class Num:
    value: int

@dataclass
class Var:
    name: str

@dataclass
class Add:
    left: 'Expr'
    right: 'Expr'

@dataclass
class Mul:
    left: 'Expr'
    right: 'Expr'

@dataclass
class Let:
    name: str
    expr: 'Expr'
    body: 'Expr'

Expr = Union[Num, Var, Add, Mul, Let]

# Environment is a list of (name, value) pairs
Env = List[Tuple[str, int]]

def lookup(name: str, env: Env) -> int:
    for var_name, value in reversed(env):
        if var_name == name:
            return value
    raise NameError(f"Variable '{name}' not found in environment")

def eval(expr: Expr, env: Env) -> int:
    if isinstance(expr, Num):
        return expr.value
    elif isinstance(expr, Var):
        return lookup(expr.name, env)
    elif isinstance(expr, Add):
        return eval(expr.left, env) + eval(expr.right, env)
    elif isinstance(expr, Mul):
        return eval(expr.left, env) * eval(expr.right, env)
    elif isinstance(expr, Let):
        val = eval(expr.expr, env)
        new_env = env + [(expr.name, val)]
        return eval(expr.body, new_env)
    else:
        raise TypeError(f"Unknown expression type: {type(expr)}")

