from __future__ import annotations
from dataclasses import dataclass
from typing import Callable


@dataclass(frozen=True)
class Leaf:
    value: int


@dataclass(frozen=True)
class Node:
    left: Tree
    value: int
    right: Tree


Tree = Leaf | Node


def mapTree(fn: Callable[[int], int], tree: Tree) -> Tree:
    if isinstance(tree, Leaf):
        return Leaf(fn(tree.value))
    return Node(
        mapTree(fn, tree.left),
        fn(tree.value),
        mapTree(fn, tree.right)
    )


def foldTree(fn: Callable[[int, int], int], acc: int, tree: Tree) -> int:
    if isinstance(tree, Leaf):
        return fn(acc, tree.value)
    left_acc = foldTree(fn, acc, tree.left)
    current_acc = fn(left_acc, tree.value)
    return foldTree(fn, current_acc, tree.right)


def treeToList(tree: Tree) -> list[int]:
    result = []

    def traverse(t: Tree) -> None:
        if isinstance(t, Leaf):
            result.append(t.value)
        else:
            traverse(t.left)
            result.append(t.value)
            traverse(t.right)

    traverse(tree)
    return result


def treeDepth(tree: Tree) -> int:
    if isinstance(tree, Leaf):
        return 1
    return 1 + max(treeDepth(tree.left), treeDepth(tree.right))


if __name__ == "__main__":
    tree = Node(
        Node(Leaf(1), 2, Leaf(3)),
        4,
        Node(Leaf(5), 6, Leaf(7))
    )

    print(treeToList(tree))
    print(treeToList(mapTree(lambda x: x * 2, tree)))
    print(foldTree(lambda acc, x: acc + x, 0, tree))
    print(treeDepth(tree))

