module benchmark/solution

type Type = TVar(string) | TInt | TBool | TFunc(Type, Type)

type MaybeType = Found(Type) | NotFound

type UnifyResult = Success([(string, Type)]) | Fail

pure func lookupSubst(subst: [(string, Type)], name: string) -> MaybeType =
  match subst {
    [] => NotFound,
    (v, ty) :: rest => if v == name then Found(ty) else lookupSubst(rest, name)
  }

pure func apply(subst: [(string, Type)], typ: Type) -> Type =
  match typ {
    TVar(name) => match lookupSubst(subst, name) {
      Found(ty) => ty,
      NotFound => TVar(name)
    },
    TInt => TInt,
    TBool => TBool,
    TFunc(arg, res) => TFunc(apply(subst, arg), apply(subst, res))
  }

pure func unifyFuncs(a1: Type, r1: Type, a2: Type, r2: Type) -> UnifyResult =
  match unify(a1, a2) {
    Success(s1) => match unify(r1, r2) {
      Success(s2) => Success(s1 ++ s2),
      Fail => Fail
    },
    Fail => Fail
  }

pure func unify(t1: Type, t2: Type) -> UnifyResult =
  match t1 {
    TInt => match t2 {
      TInt => Success([]),
      TVar(a) => Success([(a, TInt)]),
      _ => Fail
    },
    TBool => match t2 {
      TBool => Success([]),
      TVar(a) => Success([(a, TBool)]),
      _ => Fail
    },
    TVar(a) => Success([(a, t2)]),
    TFunc(a1, r1) => match t2 {
      TVar(a) => Success([(a, t1)]),
      TFunc(a2, r2) => unifyFuncs(a1, r1, a2, r2),
      _ => Fail
    }
  }

pure func showType(typ: Type) -> string =
  match typ {
    TVar(name) => name,
    TInt => "TInt",
    TBool => "TBool",
    TFunc(arg, res) => "TFunc(${showType(arg)}, ${showType(res)})"
  }

func printBinding(name: string, subst: [(string, Type)]) -> () ! {IO} =
  match lookupSubst(subst, name) {
    Found(typ) => println("${name} = ${showType(typ)}"),
    NotFound => println("${name} = <missing>")
  }

export func main() -> () ! {IO} {
  let t1 = TFunc(TVar("a"), TInt);
  let t2 = TFunc(TBool, TVar("b"));
  match unify(t1, t2) {
    Success(subst) => {
      printBinding("a", subst);
      printBinding("b", subst)
    },
    Fail => println("fail")
  }
}

