from dataclasses import dataclass
from typing import Union, List

@dataclass
class TVar:
    name: str

@dataclass
class TInt:
    pass

@dataclass
class TBool:
    pass

@dataclass
class TFunc:
    arg: 'Type'
    result: 'Type'

Type = Union[TVar, TInt, TBool, TFunc]
Substitution = List[tuple]

def apply(subst: Substitution, t: Type) -> Type:
    if isinstance(t, TVar):
        for var, typ in subst:
            if var == t.name:
                return typ
        return t
    elif isinstance(t, TFunc):
        return TFunc(apply(subst, t.arg), apply(subst, t.result))
    else:
        return t

def unify(t1: Type, t2: Type) -> Substitution:
    if isinstance(t1, TInt) and isinstance(t2, TInt):
        return []
    elif isinstance(t1, TBool) and isinstance(t2, TBool):
        return []
    elif isinstance(t1, TVar) and isinstance(t2, TVar):
        if t1.name == t2.name:
            return []
        else:
            return [(t1.name, t2)]
    elif isinstance(t1, TVar):
        return [(t1.name, t2)]
    elif isinstance(t2, TVar):
        return [(t2.name, t1)]
    elif isinstance(t1, TFunc) and isinstance(t2, TFunc):
        s1 = unify(t1.arg, t2.arg)
        s2 = unify(apply(s1, t1.result), apply(s1, t2.result))
        return s1 + s2
    else:
        raise ValueError("unify fail")

def type_to_string(t: Type) -> str:
    if isinstance(t, TVar):
        return f"TVar({t.name!r})"
    elif isinstance(t, TInt):
        return "TInt"
    elif isinstance(t, TBool):
        return "TBool"
    elif isinstance(t, TFunc):
        return f"TFunc({type_to_string(t.arg)}, {type_to_string(t.result)})"
    return str(t)

if __name__ == "__main__":
    t1 = TFunc(TVar("a"), TInt)
    t2 = TFunc(TBool, TVar("b"))

    subst = unify(t1, t2)

    result = {}
    for var, typ in subst:
        result[var] = typ

    if "a" in result:
        print(f"a = {type_to_string(result['a'])}")
    if "b" in result:
        print(f"b = {type_to_string(result['b'])}")
